const CACHE = 'shichu-jidou-v271';  /* (1)用語を流派に合わせ「身強」→「身旺（みおう）」に統一（複合語は身旺・身弱）。(2)身旺・身弱の上書きボタンを「⚙詳細設定」の中から、鑑定バーの常時表示位置へ移動（鑑定書を見ながら即切替できるように）。上書き→喜神・忌神・会局色・ラッキーカラー・養生の文章まで連動＋別人で自動リセットは従来通り。※v249=日支の通根を追加。※v248=月令点導入＋比劫印カウント撤去。 ※v252=上書き時に守護神(喜神)が空になる不具合を修正。※v253=全体点検：上書き時に守護神パネル(#shugoWrap)も追随していなかったのを修正。命式表の身旺/身弱ラベル・守護神パネル・鑑定書の文言・喜神忌神・会局色まで、ボタン1つで完全連動（UI操作で検証）。 ※v254=月運にも「巡る吉凶星」を追加（大運・年運と同じ照合ロジック＝月支基準/三合基準/日干基準。今月の運気パネル＋鑑定文に反映。短期・影響小と明記）。 ※v255=「目の前の運（日運・月運）」セクションを新設。日付/月を選んで照会＋今日から2週間の日運一覧＋これから12ヶ月の月運一覧。各々に良い日/注意日の目安（身旺身弱＋喜神忌神）・巡る吉凶星・命式との合冲・過ごし方を表示。鑑定文にも近運の山谷を提供。計算エンジンは非改変。 ※v256=日運・月運の各タブに「この日/この月をAIで鑑定」ボタンを追加。選んだ日/月に絞った短い鑑定文をワンタップ生成（既存のサーバー中継Gemini＋オフライン自動フォールバック＋1日上限を流用）。日付/月を変えるとAI文は自動クリア。スマホ配慮の全幅ボタン(48px)。 ※v257=表記整理：ボタン名を「この日/この月を詳細鑑定」に変更し、絵文字を撤去（CLAUDE.mdの「サイト内で『AI』の語を使わない」に準拠。詳細鑑定＝オンライン鑑定の呼称）。日運・月運タブの絵文字も撤去。 ※v258=鑑定者の承認により、日運・月運の詳細鑑定ボタンだけ例外的に「この日をAIで詳細鑑定する／この月をAIで詳細鑑定する」と表記（CLAUDE.mdに例外を明記）。長い文言でもボタンが崩れないようCSS調整。 ※v259=重要修正：サーバー関数の最終ユーザーメッセージ上限MAX_BODYが12000字で、命式全文を渡す自動の詳細鑑定(最大約24300字)が413で弾かれオンライン生成できず常にオフラインへ落ちていた不具合を修正（MAX_BODY=40000へ）。近運の詳細鑑定(約490字)は元々上限内で影響なし。 ※v260=冗長・繰り返し対策を強化：全AI鑑定の共通指示に「各段落は新しい論点だけ・前段落の言い換え禁止・要約段落を作らない・水増し禁止」を追加（generateReadingのsystemに連結。詳細鑑定/相談/相性/日運月運すべてに適用）。 ※v261=鑑定文を「画像で共有」ボタンを追加（鑑定文の下）。自前canvasで鑑定文を画像化し、navigator.shareのファイル共有でLINE等に1タップ添付（スマホ）。非対応端末は画像を保存へフォールバック、失敗時はテキスト共有へ。外部ライブラリ不使用・オフライン可。長文は倍率を自動で下げメモリ肥大を防止。既存機能は非改変（ボタン追加のみ）。 ※v262=鑑定者の要望で「画像で共有」ボタンを撤去（一色べた文字で長く読みづらいため）。鑑定書の共有は「PDF」を標準に：既存の「🖨印刷/PDF保存」が色見出し・太字ハイライト付きの整った鑑定書を出すので、印刷画面にスマホでLINEにPDF送付する手順ガイドを追記（実際のPDFには非表示）。相手はPDFを保存・拡大・印刷できる。 ※v263=PDFの体裁を仕上げ：印刷CSSに改ページ制御を追加（見出しをページ末に孤立させない・段落や箇条書きを途中で切らない・要約枠を分割しない・A4余白14mm）。実A4出力で5ページとも綺麗に改ページされることを確認。 ※v264=命式表ページ(meishi-sheet)にも屋号ヘッダーを追加。app-proで保存した屋号・差し色・ロゴ(localStorage)を読み、命式表(横型.yk-head含む)・鑑定書の各ヘッダー上部に屋号バンドを差し込む（未設定なら標準ヘッダーのまま）。横型はJS生成のため生成後・印刷直前・DOM変化時に再適用。meishiki-originalへバイト単位ミラー済み。 ※v265=屋号が幅を取り鑑定書の内容を押し出す問題に対応：屋号バンドを全幅の帯から「右上に小さく（絶対配置・高さを増やさない）」へ変更。屋号優先で内容がはみ出すことがなくなる（内容優先）。 ※v266=(1)屋号(スクール名)未入力時は空欄化＝印刷/共有で「（スクール名を入力）」を出さない（画面はうすいヒントのみ、区切り「・」も消す）。(2)命式表(横型)の文字を一段小さく＋主要セルを太字に、行の詰めと縮小下限(0.78→0.72)も調整し、文章が多い命式でも下端(時柱の下線)が切れにくくした。meishiki-originalへミラー済み。 ※v267=app-proの右下に小さく薄いバージョン表示を追加（sw.jsのCACHE版を自動取得＝デプロイ版が一目で分かる／印刷には出さない）。※LPが出ないのは仕様（利用済み端末はindex.htmlからapp-proへ自動遷移。LP再表示は?lp=1）。 ※v268=鑑定文の不具合修正：日柱説明などカッコ（）内に「。」を含む文が、文の区切りでカッコの途中で切れて「）で、これが…」という孤立行になっていたのを修正（formatReadingの文分割をカッコ内の「。」では区切らないように）。オンライン鑑定文にも一括で効く。命式表つき鑑定書(meishi-sheet)は段落そのままで元から問題なし。 ※v269=寿ゾーン(結婚時期)が現実離れした遠い年(数十年先)を出す不具合を修正。配偶者星が主役の大運が「今から10年より先」の命式では、遠い起承転結を見出しに出さず、代わりに何歳ごろ(西暦)にその大運が来るかを一言添えたうえで、近い将来の実用的なタイミング(配偶者星が巡る年・干合・支合・天地徳合・三合＝いずれも既存の算出)を出会い・結婚の目安として案内。大運が現在進行中/近い場合は従来どおり起承転結を表示。日付は元から正しく認識(今日基準で年齢計算)しており日付バグではなく仕様の問題を是正。鑑定文(恋愛)にも同じ分岐を反映。計算エンジンは非改変・表示層のみ。 ※v270=(1)命式表(年運12年)の「吉凶星・記入」列で、空欄セルに出していたプレースホルダ「（自由記入）」を撤去し真の空白に（手書き・入力の妨げを解消。meishiki-originalへバイト単位ミラー済み）。(2)寿ゾーンに「大運の配偶者星以外の結婚・恋愛の暗示」を追加：桃花(咸池)・紅艶が年運で巡る年(今後12年)を「恋愛・魅力が高まり異性の縁が動きやすい年」として近縁セクション＋鑑定文に表示。配偶者星の大運が遠い命式でも、年運ベースの実用的なタイミングで読めるよう強化。既存の吉凶星照合(meguriKichi)を流用・計算エンジン非改変。 ※v271=桃花・紅艶の意味が一目で分かるよう、説明の先頭に「モテ期」を赤字で明示（異性の縁・魅力が高まる年）。表示文言のみの調整。 */

/* 初回訪問時に先読みしてキャッシュするページ一式（このブランドのみ） */
const ASSETS = [
  'icon-192.png', 'icon-512.png', 'apple-touch-icon.png', 'icon-maskable-512.png', 'icon-crystal.png',
  'app-pro.html', 'meishi-sheet.html', 'index.html', 'textbook-pro.html',
  'pricing-pro.html', 'mypage-pro.html', 'auth.html',
  'terms-pro.html', 'tokushoho-pro.html', 'privacy-pro.html',
  'manifest-pro.webmanifest', 'icon-pro.svg',
  'pklove.js',
  'jikkan.html', 'tsuhensei.html', 'juniun.html', 'zohkan.html', 'kubo.html',
  'daiun-tenkanki.html', 'ritsuun.html', 'nichiza-tenchusatsu.html', 'ijokanshi.html',
  'kanshi-aisho.html', 'aisho-pattern.html', 'daiun-tsuhen.html', 'setsuboku.html', 'tensen-chichu.html', 'nayin-aisho.html', 'boko-kaichu.html', 'kaikyoku.html', 'inyoku.html', 'nichiza.html', 'kodoku.html'
];

self.addEventListener('install', (e) => {
  e.waitUntil(
    caches.open(CACHE)
      .then((c) => Promise.all(ASSETS.map((u) => c.add(u).catch(() => null))))
      .then(() => self.skipWaiting())
  );
});

self.addEventListener('activate', (e) => {
  e.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

self.addEventListener('fetch', (e) => {
  const req = e.request;
  if (req.method !== 'GET') return;                       // 送信系はそのまま
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;        // 生成AI等の外部通信は素通し

  // stale-while-revalidate：まずキャッシュを即返し、裏で最新を取り直して次回に備える
  e.respondWith(
    caches.open(CACHE).then((cache) =>
      cache.match(req).then((cached) => {
        const network = fetch(req).then((res) => {
          if (res && res.status === 200 && res.type === 'basic') cache.put(req, res.clone());
          return res;
        }).catch(() => null);
        return cached || network.then((res) => res || cache.match('app-pro.html'));
      })
    )
  );
});
